import { HexBigIntCompat } from "../schemas.js";
import { object, z } from "../zod.js";

export const MultiDimensionalNonceCapability = object({
  // we do not support the optional sequentialNonce param
  nonceKey: HexBigIntCompat({
    description: "Override nonce key as hex string",
  }),
});

export type MultiDimensionalNonceCapability = z.input<
  typeof MultiDimensionalNonceCapability
>;
